{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "BI 425809, a complex lipophilic carboxylic acid, showed 71.6% absolute oral bioavailability in humans, demonstrating that high F is achievable despite a challenging physicochemical profile.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Trametinib, a high-molecular-weight, highly functionalized drug, had mean absolute oral bioavailability of 72.3% in patients, supporting high F for the query despite multiple hydrogen-bonding groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Sunitinib, which contains a basic amine and multiple hydrogen-bond acceptors, has absolute oral bioavailability around 50% in humans, supporting F ≥ 20% for the ionizable query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Amphotericin B, a large polyhydroxylated macrocycle, has negligible oral bioavailability, providing a structurally relevant counterexample that supports low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer human absolute bioavailability evidence supports F ≥ 20%: BI 425809 (72%), trametinib (72%), sunitinib (~50%), ofloxacin (~100%), and nevirapine (~90%) all show high oral bioavailability despite substantial polarity or ionization. The amphotericin B low-F example is a relevant macrocyclic counterexample, but it is outweighed by the multiple high-F analogues with comparable or higher transfer scores. The physicochemical prior is low, but direct human F evidence overrides it.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "Amphotericin B is structurally relevant but not identical; its negligible F may reflect polyene-specific instability and very low permeability beyond the query's features.",
    "Uncertainty remains about possible active transport, prodrug behavior, or formulation effects that could alter oral absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

